import numpy as np
from scipy.optimize import fsolve

def solve_for_k(k):
    def equations(vars):
        a, b, c = vars
        return [a - b - k*b*c, b - c - k*c*a, c - a - k*a*b]

    # Try several different starting points
    results = []
    for guess in [[1, 2, 3], [1, -2, 3], [-1, 2, 3], [2, 1, -1], [3, 2, 1], [1, 1, 1]]:
        sol = fsolve(equations, guess)
        a, b, c = sol
        if a != 0 and b != 0 and c != 0:
            results.append((a, b, c))
    return results

for k in [1, 2, 3, 4, 5]:
    sols = solve_for_k(k)
    for a, b, c in sols:
        # Check if it's a real solution
        if np.isreal(a) and np.isreal(b) and np.isreal(c):
            print(f"k={k}: a={a}, b={b}, c={c}, sum={a/c + b/a + c/b}")

import numpy as np
from scipy.optimize import fsolve

def equations(vars, k):
    a, b, c = vars
    return [a - b - k*b*c, b - c - k*c*a, c - a - k*a*b]

# Try a few values of k and different starting points
for k in [1, 2, 3]:
    for guess in [[1, 2, 3], [1, -2, 3], [-1, 2, 3], [2, 1, -1], [3, 2, 1], [1, 1, 1], [2, 2, 2]]:
        sol = fsolve(equations, guess, args=(k,))
        a, b, c = sol
        if a != 0 and b != 0 and c != 0:
            # Check if the solution is valid
            if np.isclose(a-b, k*b*c) and np.isclose(b-c, k*c*a) and np.isclose(c-a, k*a*b):
                print(f"k={k}: a={a}, b={b}, c={c}, sum={a/c + b/a + c/b}")
